const mailboxes = $input.first().json.data?.mailboxes;
if (!Array.isArray(mailboxes)) throw new Error('Unexpected account response; no mailbox operations attempted.');
if (mailboxes.length !== 1 || mailboxes[0].address?.toLowerCase() !== 'hello@cinematicflight.com') throw new Error('Token does not show exactly the intended hello mailbox. Review mailbox scope before proceeding.');
const box = mailboxes[0];
if (typeof box.resourceId !== 'string' || !box.resourceId) throw new Error('Missing mailbox identifier.');
return [{json:{connectionVerified:true,mailboxAddress:box.address,mailboxResourceId:box.resourceId,visibleMailboxCount:mailboxes.length,scopeCaveat:'Confirms currently visible mailboxes only; verify Selected mailboxes in Hostinger.',emailsRead:0,messagesSent:0,mailboxChanges:0,aiCalls:0,nextAction:'Designate a synthetic test email before connecting any message content to AI.'}}];
